-- Table structure for table `remote_commands_remotecommand`
--

DROP TABLE IF EXISTS `remote_commands_remotecommand`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `remote_commands_remotecommand` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `command` longtext NOT NULL,
  `timeout` int unsigned NOT NULL,
  `created_at` datetime(6) NOT NULL,
  `status` varchar(16) NOT NULL,
  `stdout` longtext NOT NULL,
  `stderr` longtext NOT NULL,
  `returncode` int DEFAULT NULL,
  `executed_at` datetime(6) DEFAULT NULL,
  `created_by_id` int DEFAULT NULL,
  `device_id` bigint DEFAULT NULL,
  `shell` varchar(16) NOT NULL,
  `working_directory` varchar(1024) NOT NULL,
  `cancel_requested` tinyint(1) NOT NULL,
  PRIMARY KEY (`id`),
  KEY `remote_commands_remo_created_by_id_7f3d3ab7_fk_auth_user` (`created_by_id`),
  KEY `remote_commands_remo_device_id_310cc2c4_fk_devices_d` (`device_id`),
  CONSTRAINT `remote_commands_remo_created_by_id_7f3d3ab7_fk_auth_user` FOREIGN KEY (`created_by_id`) REFERENCES `auth_user` (`id`),
  CONSTRAINT `remote_commands_remo_device_id_310cc2c4_fk_devices_d` FOREIGN KEY (`device_id`) REFERENCES `devices_device` (`id`),
  CONSTRAINT `remote_commands_remotecommand_chk_1` CHECK ((`timeout` >= 0))
) ENGINE=InnoDB AUTO_INCREMENT=85 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
